{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.HealthyMaster_zepto_sales_fact_items_intermediate as select EAN, concat(EAN,sku_number,city,date,Gross_Merchandise_Value) as order_item, CAST(MRP AS FLOAT64) AS MRP, CITY, CAST(Date AS timestamp) as Order_Date, SKU_NAME AS Product_name, Brand_Name as Brand, sku_number, sku_category, cast(Gross_Merchandise_Value as float64) as selling_price, manufacturer_id, SKU_Sub_Category as sub_category, cast(Gross_Merchandise_Value as float64) as Gross_Selling_Value, cast(Sales__Qty____Units as int64) as quantity, cast(Gross_Merchandise_Value as float64) as Gross_Merchandise_Value from `MAPLEMONK.zepto_HM_sales` ; create or replace table maplemonk.HealthyMaster_zepto_sales_fact_items as select z.*, sm.Product_title as product_name_final, sm.category as Product_category, sm.Product_Type FROM maplemonk.HealthyMaster_zepto_sales_fact_items_intermediate z left join (select Product_title, Product_Type, Category, Market_place_product_ID sku_code, Market_place_products_name from maplemonk.google_sheets_sku_master where lower(platform) like \'%zepto%\' qualify row_number() over (partition by lower(replace(Market_place_product_ID,\' \',\'\')) order by 1)=1 ) sm on lower(replace(z.sku_number,\' \',\'\')) = lower(replace(sm.sku_code,\' \',\'\')) ; CREATE OR REPLACE TABLE MapleMonk.HealthyMaster_Zepto_Ads_Fact_Items AS WITH Sponsored_Display AS ( SELECT CAST(Atc AS INT64) AS Atc, CAST(Cpm AS FLOAT64) AS Cpm, CAST(Ctr AS FLOAT64) AS Ctr, PARSE_DATE(\'%Y-%m-%d\', Date) AS Date, CAST(Roas AS FLOAT64) AS Roas, CAST(Spend AS FLOAT64) AS Spend, CAST(Clicks AS INT64) AS Clicks, CAST(Orders AS INT64) AS Orders, CAST(BrandID AS STRING) AS BrandID, CAST(Revenue AS FLOAT64) AS Revenue, CAST(BrandName AS STRING) AS BrandName, CAST(ProductID AS STRING) AS ProductID, CAST(Same_skus AS STRING) AS Same_skus, CAST(Other_skus AS STRING) AS Other_skus, CAST(Campaign_id AS STRING) AS Campaign_id, CAST(Impressions AS INT64) AS Impressions, CAST(ProductName AS STRING) AS ProductName, CAST(Campaign_name AS STRING) AS Campaign_name, \'Display\' AS Type FROM `MapleMonk.zepto_HM_sponsored_display` sd ), Sponsored_Products AS ( SELECT CAST(Atc AS INT64) AS Atc, CAST(Cpm AS FLOAT64) AS Cpm, CAST(Ctr AS FLOAT64) AS Ctr, PARSE_DATE(\'%Y-%m-%d\', Date) AS Date, CAST(Roas AS FLOAT64) AS Roas, CAST(Spend AS FLOAT64) AS Spend, CAST(Clicks AS INT64) AS Clicks, CAST(Orders AS INT64) AS Orders, CAST(BrandID AS STRING) AS BrandID, CAST(Revenue AS FLOAT64) AS Revenue, CAST(BrandName AS STRING) AS BrandName, CAST(ProductID AS STRING) AS ProductID, CAST(Same_skus AS STRING) AS Same_skus, CAST(Other_skus AS STRING) AS Other_skus, CAST(Campaign_id AS STRING) AS Campaign_id, CAST(Impressions AS INT64) AS Impressions, CAST(ProductName AS STRING) AS ProductName, CAST(Campaign_name AS STRING) AS Campaign_name, \'Product\' AS Type FROM `MapleMonk.zepto_HM_sponsored_products` sp ) SELECT Atc, Cpm, Ctr, Date, Roas, Spend, Clicks, Orders, BrandID, Revenue, BrandName, ProductID, Same_skus, Other_skus, Campaign_id, Impressions, ProductName, Campaign_name, Type FROM Sponsored_Display UNION ALL SELECT Atc, Cpm, Ctr, Date, Roas, Spend, Clicks, Orders, BrandID, Revenue, BrandName, ProductID, Same_skus, Other_skus, Campaign_id, Impressions, ProductName, Campaign_name, Type FROM Sponsored_Products;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            